    paint = max((v for v in counts if v not in (bg, edge)),
                key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Process each colored border cell's inward ray. Border runs also
    # contribute their central ray(s) when no target lies on that ray.
    def cast(ray):
        hit = next((i for i, (r, c) in enumerate(ray)
                    if grid[r][c] == paint), None)
        stop = hit if hit is not None else len(ray)
        for r, c in ray[:stop]:
            out[r][c] = paint
        if hit is not None:
            r, c = ray[hit]
            out[r][c] = 4

    def process_side(coords, make_ray):
        # coords are ordered along one edge; split marker pixels into runs
        runs = []
        run = []
        for p in coords + [None]:
            if p is not None and grid[p[0]][p[1]] == edge:
                run.append(p)
            else:
                if run:
                    runs.append(run)
                    run = []
        for run in runs:
            n = len(run)
            # Central position(s); for longer even runs use the upper center.
