                 lambda p: [(p[0], c) for c in range(1, w)])
    process_side([(r, w - 1) for r in range(h)],
                 lambda p: [(p[0], c) for c in range(w - 2, -1, -1)])
    process_side([(0, c) for c in range(w)],
